import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/math-clever-calc-2.svg",g=JSON.parse('{"title":"奥数进阶：速算与巧算（二）基准数与分组的艺术","description":"当算式中的数字变多、变大，简单的凑整可能不再够用。本文带你学习更高级的“基准数法”和“分组法”，让你在处理长串加减法时游刃有余。","frontmatter":{"title":"奥数进阶：速算与巧算（二）基准数与分组的艺术","date":"2026-02-16T09:00:00.000Z","categories":["数学"],"tags":["小学奥数","计算技巧","基准数法","分组凑整"],"description":"当算式中的数字变多、变大，简单的凑整可能不再够用。本文带你学习更高级的“基准数法”和“分组法”，让你在处理长串加减法时游刃有余。","cover":"/img/math-clever-calc-2.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-olympiad-calc-2.md","filePath":"posts/primary-math-olympiad-calc-2.md","lastUpdated":null}'),r={name:"posts/primary-math-olympiad-calc-2.md"};function o(l,a,c,e,h,i){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="奥数进阶-速算与巧算-二-基准数与分组的艺术" tabindex="-1">奥数进阶：速算与巧算（二）基准数与分组的艺术 <a class="header-anchor" href="#奥数进阶-速算与巧算-二-基准数与分组的艺术" aria-label="Permalink to &quot;奥数进阶：速算与巧算（二）基准数与分组的艺术&quot;">​</a></h1><p>在掌握了基础的“好朋友”凑整法后，我们经常会遇到一些更有挑战性的题目。比如，一串数字都很大，但它们都非常接近某个数；或者算式非常长，看起来毫无头绪。</p><p>这时候，我们需要请出两位“高级特工”：<strong>基准数法</strong>和<strong>分组法</strong>。</p><hr><h2 id="一、-基准数法-寻找数字的-核心" tabindex="-1">一、 基准数法：寻找数字的“核心” <a class="header-anchor" href="#一、-基准数法-寻找数字的-核心" aria-label="Permalink to &quot;一、 基准数法：寻找数字的“核心”&quot;">​</a></h2><p>当一组数都比较接近某个整十、整百数时，我们可以把这个数作为“基准”。</p><p><img src="'+p+'" alt="基准数法示意图"></p><p><strong>【解题步骤】</strong>：</p><ol><li><strong>找基准</strong>：选一个大家都接近的整十、整百数。</li><li><strong>算总和</strong>：基准数 × 个数。</li><li><strong>补差额</strong>：多算的减掉，少算的加上。</li></ol><p><strong>【例题 1】</strong>：计算 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>9</mn><mn>8</mn><mo>+</mo><mn>5</mn><mn>0</mn><mn>3</mn><mo>+</mo><mn>4</mn><mn>9</mn><mn>6</mn><mo>+</mo><mn>5</mn><mn>0</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">498 + 503 + 496 + 505</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">9</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mord mathrm">9</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mord mathrm">5</span></span></span></span><strong>解析</strong>：</p><ol><li>这些数都接近 500，选 500 为基准数。</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mn>0</mn><mn>0</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>2</mn><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">500 \\times 4 = 2000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</li><li>补差：-2 (\\text{498比500少2}) + 3 (\\text{503比500多3}) - 4 (\\text{496比500少4}) + 5 (\\text{505比500多5})。</li><li>差额合计：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>−</mo><mn>2</mn><mo>+</mo><mn>3</mn><mo>−</mo><mn>4</mn><mo>+</mo><mn>5</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">-2 + 3 - 4 + 5 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord">−</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span>。</li><li>总结果：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>2</mn><mn>0</mn><mn>0</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">2000 + 2 = 2002</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">2</span></span></span></span>。 <strong>答案</strong>：2002。</li></ol><hr><h2 id="二、-分组法-化繁为简的魔法" tabindex="-1">二、 分组法：化繁为简的魔法 <a class="header-anchor" href="#二、-分组法-化繁为简的魔法" aria-label="Permalink to &quot;二、 分组法：化繁为简的魔法&quot;">​</a></h2><p>当加法和减法交替出现，且有一定的规律时，我们可以把它们“两两分组”。</p><p><strong>【例题 2】</strong>：计算 100 - 99 + 98 - 97 + 96 - 95 + \\dots + 2 - 1 <strong>解析</strong>：</p><ol><li>观察规律：每两项相减都等于 1。</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>9</mn><mn>9</mn><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">100 - 99 = 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mord mathrm">1</span></span></span></span>，98 - 97 = 1 \\dots</li><li>一共有多少组？从 1 到 100 有 100 个数，两两一组，共有 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>5</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">100 \\div 2 = 50</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span></span></span></span> 组。</li><li>总结果：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mn>0</mn><mo>×</mo><mn>1</mn><mo>=</mo><mn>5</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">50 \\times 1 = 50</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span></span></span></span>。 <strong>答案</strong>：50。</li></ol><hr><h2 id="三、-进阶模型-带有-9-的系列" tabindex="-1">三、 进阶模型：带有“9”的系列 <a class="header-anchor" href="#三、-进阶模型-带有-9-的系列" aria-label="Permalink to &quot;三、 进阶模型：带有“9”的系列&quot;">​</a></h2><p><strong>【技巧】</strong>：看到 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mo separator="true">,</mo><mn>9</mn><mn>9</mn><mo separator="true">,</mo><mn>9</mn><mn>9</mn><mn>9</mn></mrow><annotation encoding="application/x-tex">9, 99, 999</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.8388800000000001em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mpunct">,</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mpunct">,</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span></span></span></span>，立刻想到 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">10-1, 100-1, 1000-1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.8388800000000001em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mpunct">,</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mpunct">,</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span></span></span></span>。</p><p><strong>【例题 3】</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mo>+</mo><mn>9</mn><mn>9</mn><mo>+</mo><mn>9</mn><mn>9</mn><mn>9</mn><mo>+</mo><mn>9</mn><mn>9</mn><mn>9</mn><mn>9</mn></mrow><annotation encoding="application/x-tex">9 + 99 + 999 + 9999</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span></span></span></span><strong>解析</strong>： <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>0</mn><mo>−</mo><mn>1</mn><mo>)</mo><mo>+</mo><mo>(</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>1</mn><mo>)</mo><mo>+</mo><mo>(</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>1</mn><mo>)</mo><mo>+</mo><mo>(</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>−</mo><mn>1</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">(10-1) + (100-1) + (1000-1) + (10000-1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span></span></span></span><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mo>(</mo><mn>1</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>)</mo><mo>−</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">= (10+100+1000+10000) - 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mclose">)</span><span class="mbin">−</span><span class="mord mathrm">4</span></span></span></span><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>1</mn><mn>1</mn><mn>1</mn><mn>1</mn><mn>0</mn><mo>−</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>1</mn><mn>1</mn><mn>0</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">= 11110 - 4 = 11106</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">6</span></span></span></span>。</p><hr><h2 id="四、-避坑指南-正负号的纠缠" tabindex="-1">四、 避坑指南：正负号的纠缠 <a class="header-anchor" href="#四、-避坑指南-正负号的纠缠" aria-label="Permalink to &quot;四、 避坑指南：正负号的纠缠&quot;">​</a></h2><p>在使用分组法时，一定要看清每个数字前面的符号。</p><ul><li><strong>提醒</strong>：如果第一项是负的，或者规律发生了变化（比如中间漏了数字），一定要先补齐再计算。</li></ul><hr><h2 id="五、-练一练-巧算大师闯关" tabindex="-1">五、 练一练（巧算大师闯关） <a class="header-anchor" href="#五、-练一练-巧算大师闯关" aria-label="Permalink to &quot;五、 练一练（巧算大师闯关）&quot;">​</a></h2><ol><li><strong>基准数关</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>7</mn><mo>+</mo><mn>1</mn><mn>0</mn><mn>4</mn><mo>+</mo><mn>1</mn><mn>0</mn><mn>1</mn><mo>+</mo><mn>9</mn><mn>9</mn><mo>+</mo><mn>1</mn><mn>0</mn><mn>2</mn><mo>=</mo><mo>?</mo></mrow><annotation encoding="application/x-tex">97 + 104 + 101 + 99 + 102 = ?</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">7</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mclose">?</span></span></span></span></li><li><strong>分组关</strong>：1 + 2 - 3 + 4 + 5 - 6 + \\dots + 28 + 29 - 30 = ?</li><li><strong>挑战关</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mo>+</mo><mn>9</mn><mn>8</mn><mo>+</mo><mn>9</mn><mn>9</mn><mn>7</mn><mo>+</mo><mn>9</mn><mn>9</mn><mn>9</mn><mn>6</mn><mo>=</mo><mo>?</mo></mrow><annotation encoding="application/x-tex">9 + 98 + 997 + 9996 = ?</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.77777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">7</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">9</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mclose">?</span></span></span></span></li></ol><hr><p><em>总结：巧算二的核心在于“转化”。把大数变小数，把长算式变短算式。多观察、多尝试，你会发现计算也是一种艺术！</em></p>',29)])])}const x=s(r,[["render",o]]);export{g as __pageData,x as default};
